{"path": "/tmp/sv-a0ada4f31bde48a39b5a4cd8da9018a6/Components/Pages/Apply/PersonalInfoStep.razor", "file_text": "@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-banner">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Info.FullName"
               @onchange="e => UpdateInfo(Info with { FullName = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Info.Email"
               @onchange="e => UpdateInfo(Info with { Email = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Info.Phone"
               @onchange="e => UpdateInfo(Info with { Phone = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Info.Address"
                  @onchange="e => UpdateInfo(Info with { Address = (string?)e.Value ?? "" })"></textarea>
    </div>

    <div class="step-buttons">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Models.PersonalInfo Info { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<Models.PersonalInfo> OnInfoChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private void UpdateInfo(Models.PersonalInfo updated) => OnInfoChanged.InvokeAsync(updated);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Info.FullName) ||
            string.IsNullOrWhiteSpace(Info.Email) ||
            string.IsNullOrWhiteSpace(Info.Phone) ||
            string.IsNullOrWhiteSpace(Info.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Info.Email);
            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}
"}

{"path": "/tmp/sv-a0ada4f31bde48a39b5a4cd8da9018a6/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="e => HandleEntryChanged(index, e)"
                       OnRemove="() => HandleRemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Models.WorkEntry> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<Models.WorkEntry>> OnEntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleEntryChanged(int index, Models.WorkEntry updated)
    {
        var list = new List<Models.WorkEntry>(Entries);
        list[index] = updated;
        OnEntriesChanged.InvokeAsync(list);
    }

    private void HandleRemoveEntry(int index)
    {
        var list = new List<Models.WorkEntry>(Entries);
        list.RemoveAt(index);
        OnEntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<Models.WorkEntry>(Entries)
        {
            new("", "", DateTime.Today, null, "")
        };
        OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        var hasValid = Entries.Any(e =>
            !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title));
        if (!hasValid)
        {
            ErrorMessage = "Please complete at least one work entry with company and title.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-a0ada4f31bde48a39b5a4cd8da9018a6/Components/Pages/Apply/ReferencesStep.razor", "file_text": "@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 2)"
                       OnChanged="e => HandleReferenceChanged(index, e)"
                       OnRemove="() => HandleRemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-banner">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Models.Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<Models.Reference>> OnReferencesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleReferenceChanged(int index, Models.Reference updated)
    {
        var list = new List<Models.Reference>(References);
        list[index] = updated;
        OnReferencesChanged.InvokeAsync(list);
    }

    private void HandleRemoveReference(int index)
    {
        var list = new List<Models.Reference>(References);
        list.RemoveAt(index);
        OnReferencesChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Models.Reference>(References)
        {
            new("", "", "", "")
        };
        OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        var validCount = References.Count(r =>
            !string.IsNullOrWhiteSpace(r.Name) &&
            !string.IsNullOrWhiteSpace(r.Relationship) &&
            !string.IsNullOrWhiteSpace(r.Email));
        if (validCount < 2)
        {
            ErrorMessage = "Please provide at least 2 complete references.";
            return;
        }
        ErrorMessage = null;
        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-a0ada4f31bde48a39b5a4cd8da9018a6/Components/Pages/Apply/CoverLetterStep.razor", "file_text": "@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="HandleInput"
                  placeholder="Write your cover letter here..."></textarea>
        <span class="char-count">@CoverLetter.Length / 2000 characters</span>
    </div>

    <div class="step-buttons">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? "";
        if (value.Length > 2000) value = value[..2000];
        OnCoverLetterChanged.InvokeAsync(value);
    }
}
"}

{"path": "/tmp/sv-a0ada4f31bde48a39b5a4cd8da9018a6/Components/Pages/Apply/ReviewStep.razor", "file_text": "@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-banner">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br /><small>@r.Email · @r.Phone</small>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-buttons">
            <button class="btn-outline" @onclick="OnBack">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Models.PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<Models.WorkEntry> WorkEntries { get; set; } = new();
    [Parameter, EditorRequired] public List<Models.Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> SubmitApplication { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        try
        {
            ApplicationId = await SubmitApplication();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}
"}

