@page "/apply"
@using sv_a0ada4f31bde48a39b5a4cd8da9018a6.Models
@namespace sv_a0ada4f31bde48a39b5a4cd8da9018a6.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="@personalInfo"
                              OnInfoChanged="info => { personalInfo = info; StateHasChanged(); }"
                              OnNext="NextFromPersonalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="entries => { workEntries = entries; StateHasChanged(); }"
                             OnNext="CompleteAndAdvance"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="refs => { references = refs; StateHasChanged(); }"
                            OnNext="CompleteAndAdvance"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnCoverLetterChanged="cl => { coverLetter = cl; StateHasChanged(); }"
                             OnNext="CompleteAndAdvance"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkEntry> workEntries = new() { new("", "", DateTime.Today, null, "") };
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void CompleteAndAdvance()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void NextFromPersonalInfo()
    {
        completedSteps.Add(0);
        currentStep = 1;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

